}
.fmstr-cmp-gdr-hero__panel-title {
  margin-left: 8px;
}

.fmstr-cmp-gdr-hero__pipe {
  display: grid;
  grid-template-columns: 1fr 56px 1fr;
  gap: 0;
  align-items: stretch;
  padding: 28px 20px;
}

.fmstr-cmp-gdr-hero__tile {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  padding: 18px 12px;
  border: 1px solid var(--c-border);
  border-radius: 12px;
  background: #ffffff;
}
.fmstr-cmp-gdr-hero__tile-logo {
  height: 40px;
  padding: 0 14px;
  border-radius: 10px;
  background: #ffffff;
  border: 1px solid var(--c-border);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.fmstr-cmp-gdr-hero__tile-logo svg,
.fmstr-cmp-gdr-hero__tile-logo img {
  display: block;
  height: 22px;
  width: auto;
}
.fmstr-cmp-gdr-hero__tile-name {
  font-size: 13px;
  font-weight: 700;
  color: var(--c-fg-1);
}
.fmstr-cmp-gdr-hero__tile-status {
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: #027a48;
  display: inline-flex;
  align-items: center;
  gap: 5px;
}
.fmstr-cmp-gdr-hero__tile-status-dot {
  width: 6px;
  height: 6px;
  border-radius: 9999px;
  background: var(--c-green-500);
  box-shadow: 0 0 0 0 rgba(18, 183, 106, 0.5);
  animation: fmstr-cmp-gdr-hero-pulse 1.8s ease-out infinite;
}
@keyframes fmstr-cmp-gdr-hero-pulse {
  0% {
    box-shadow: 0 0 0 0 rgba(18, 183, 106, 0.55);
  }
  70% {
    box-shadow: 0 0 0 8px rgba(18, 183, 106, 0);
  }
  100% {
    box-shadow: 0 0 0 0 rgba(18, 183, 106, 0);
  }
}

.fmstr-cmp-gdr-hero__arrow {
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}
.fmstr-cmp-gdr-hero__arrow-line {
  position: absolute;
  left: 0;
  right: 0;
  top: 50%;
  height: 2px;
  background: repeating-linear-gradient(
    to right,
    var(--c-violet-500) 0,
    var(--c-violet-500) 6px,
    transparent 6px,
    transparent 11px
  );
  transform: translateY(-50%);
}
.fmstr-cmp-gdr-hero__arrow-tip {
  position: relative;
  width: 30px;
  height: 30px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--c-violet-500), var(--c-violet-700));
  color: #fff;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 6px 14px rgba(127, 86, 217, 0.32);
  z-index: 1;
}

.fmstr-cmp-gdr-hero__files {
  padding: 0 20px 20px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  border-top: 1px dashed var(--c-border);
  padding-top: 16px;
  margin-top: -4px;
}
.fmstr-cmp-gdr-hero__file {
  display: grid;
  grid-template-columns: 22px 1fr auto;
  gap: 10px;
  align-items: center;
  padding: 8px 10px;
  background: #f9fafb;
  border-radius: 8px;
  font-size: 12px;
}
.fmstr-cmp-gdr-hero__file-icon {
  width: 22px;
  height: 22px;
  border-radius: 5px;
  background: #e8f1fe;
  color: #1a73e8;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.fmstr-cmp-gdr-hero__file-name {
  color: var(--c-fg-1);
  font-weight: 600;
}
.fmstr-cmp-gdr-hero__file-meta {
  color: var(--c-fg-3);
  font-size: 11px;
}

.fmstr-cmp-gdr-hero__timer {
  position: absolute;
  right: -14px;
  bottom: -22px;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 10px 14px;
  background: #ffffff;
  border: 1px solid var(--c-edge);
  border-radius: 9999px;
  font-size: 12.5px;
  font-weight: 600;
  color: var(--c-violet-700);
  box-shadow: var(--c-shadow-md);
}
.fmstr-cmp-gdr-hero__timer-num {
  font-variant-numeric: tabular-nums;
  color: var(--c-fg-1);
  font-weight: 700;
}

@media (max-width: 980px) {
