    justify-content: center;
  }
  .fmstr-cmp-gdr-hero__timer {
    position: static;
    margin-top: 18px;
  }
  .fmstr-cmp-gdr-hero__pipe {
    grid-template-columns: 1fr;
    gap: 12px;
  }
  .fmstr-cmp-gdr-hero__arrow {
    display: none;
  }
}

