  margin: 0 auto;
}

.fmstr-cmp-gdr-syncs__header {
  max-width: 760px;
  margin: 0 auto 48px;
  text-align: center;
}
.fmstr-cmp-gdr-syncs__h2 {
  margin: 0 0 14px;
  font-size: clamp(28px, 3.6vw, 42px);
  line-height: 1.12;
