}
.fmstr-cmp-gdr-syncs__file-icon--sheet {
  color: #0f9d58;
}
.fmstr-cmp-gdr-syncs__file-name {
  color: var(--c-fg-1);
  font-weight: 600;
}
.fmstr-cmp-gdr-syncs__file-meta {
  color: var(--c-fg-3);
  font-size: 10.5px;
}

@media (max-width: 1000px) {
